import org.junit.Test;
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.is;

public class PrettyPrintVisitorTest {

    private final Printer printer = new CollectingPrinter();

    @Test
    public void exprToString_AtomicallyWorks() {
        Expression e = new BinaryExpr(new VarExpr("x"), "+", new DecimalExpr(2));
        String result = PrettyPrintVisitor.exprToString(e);
        assertThat(result, is("x + 2"));
    }

    @Test
    public void exprToString_ConsistentResultForBinary() {
        Expression e = new BinaryExpr(new VarExpr("x"), "+", new DecimalExpr(2));
        String expected = "x + 2";
        String result = PrettyPrintVisitor.exprToString(e);
        assertThat(result, is(expected));
    }

    @Test
    public void exprToString_ConsistentResultForUnary() {
        Expression e = new UnaryExpr(new VarExpr("x"), "+");
        String expected = "+ x";
        String result = PrettyPrintVisitor.exprToString(e);
        assertThat(result, is(expected));
    }

    @Test
    public void visitAssignExpr_AtomicallyWorks() {
        AssigningExpr expr = new AssigningExpr(
            new PropertyPathExpr(new VarExpr("x"), "y"),
            new BinaryExpr(new VarExpr("z"), "+", new DecimalExpr(2))
        );
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        visitor.visitAssignExpr(expr);
    }

    @Test
    public void visitFunctionCallExpr_AtomicallyWorks() {
        FunctionCallExpr expr = new FunctionCallExpr(
            "func",
            new BinaryExpr(new VarExpr("x"), "+", new DecimalExpr(2))
        );
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        visitor.visitFunctionCallExpr(expr);
    }

    @Test
    public void visitAnonymousScriptExpr_AtomicallyWorks() {
        AnonymousScript expr = new AnonymousScript(
            new FunctionCallExpr("func", new BinaryExpr(new VarExpr("x"), "+", new DecimalExpr(2)))
        );
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        visitor.visitAnonymousScriptExpr(expr);
    }

    @Test
    public void visitPropertyPathExpr_AtomicallyWorks() {
        PropertyPathExpr expr = new PropertyPathExpr(new VarExpr("x"), "y", null, null);
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        visitor.visitPropertyPathExpr(expr);
    }
}

class AssigningExpr {
    private final Expression propertyPath;
    private final Expression expression;

    public AssigningExpr(Expression propertyPath, Expression expression) {
        this.propertyPath = propertyPath;
        this.expression = expression;
    }

    @Override
    public String toString() {
        return "AssigningExpr{" +
               "propertyPath=" + propertyPath +
               ", expression=" + expression +
               '}';
    }
}

class CollectingPrinter implements Printer {
    private StringBuilder builder;

    public CollectingPrinter() {
        this.builder = new StringBuilder();
    }

    @Override
    public void print(String value) {
        builder.append(value);
    }

    @Override
    public String toString() {
        return builder.toString();
    }
}
